function warehouseLayoutViewHtml(runtime) {
  const zones = runtime.config.zones || [];
  const currentZoneId = zones.some(zone => zone.id === S._layoutZone)
    ? S._layoutZone
    : zones[0]?.id || '';
  S._layoutZone = currentZoneId;
  const zone = zones.find(item => item.id === currentZoneId);
  const statusFilter = ['all','not_imported','imported','counting','history_review','variance','wms_pending','completed'].includes(S._layoutStatus)
    ? S._layoutStatus
    : 'all';
  const search = warehouseLocationKey(S._layoutSearch || '');
  const zoomOptions = [0.5,0.75,1,1.32,1.5];
  const zoom = zoomOptions.includes(Number(S._layoutZoom)) ? Number(S._layoutZoom) : 1;
  S._layoutZoom = zoom;
  const viewMode = 'matrix';
  S._layoutViewMode = 'matrix';
  const zoneRuntime = zone ? warehouseLayoutRuntimeForZone(runtime,zone) : runtime;
  const completenessText = zoneRuntime.completeness.toLocaleString(uiLocale(),{minimumFractionDigits:1,maximumFractionDigits:1});
  const hero = `<div class="warehouse-layout-hero">
    <div class="warehouse-layout-title">
      <div class="warehouse-layout-title-icon">${navIconSvg('warehouse',28)}</div>
      <div><h2>Layout คลังสินค้า</h2><p>ผังแม่ใช้ร่วมกันทุก Session · สถานะงานโหลดจากฐานข้อมูลของ Session ที่เลือกและอัปเดตอัตโนมัติ</p>
        ${runtime.config.isMaster ? `<span class="warehouse-layout-master-badge">✓ ผังแม่ รุ่น ${Number(runtime.config.masterRevision || 1).toLocaleString(uiLocale())}</span>` : ''}
        ${warehouseLayoutLiveStatusHtml(runtime)}
      </div>
    </div>
    <div class="warehouse-layout-actions">
      ${zones.length ? `<label class="warehouse-layout-control"><span>ZONE</span><select onchange="setWarehouseLayoutZone(this.value)">
        ${zones.map(item => `<option value="${escapeWmsText(item.id)}" ${item.id===currentZoneId?'selected':''}>${escapeWmsText(item.name)}</option>`).join('')}
      </select></label>` : ''}
      ${zones.length ? `<label class="warehouse-layout-control"><span>ค้นหา LOCATION</span><input value="${escapeWmsText(S._layoutSearch || '')}" placeholder="เช่น B-02-015-D" oninput="updateWarehouseLayoutSearch(this.value)"></label>` : ''}
      ${prof?.role === 'admin' ? `<button class="btn btn-ghost" type="button" onclick="openWarehouseLayoutEditor()">${navIconSvg('manage',17)} ตั้งค่าผังแม่</button>` : ''}
      ${zones.length ? `<button class="btn btn-blue" type="button" onclick="showWarehouseLayoutMatchReport(false,'${escapeWmsText(currentZoneId)}')">ตรวจสอบและจับคู่</button>` : ''}
      ${zones.length ? `<button class="btn btn-ghost" type="button" onclick="showWarehouseSnapshotAuditReport('${escapeWmsText(currentZoneId)}')">ดูข้อมูล Item</button>` : ''}
    </div>
  </div>`;
  if (!zones.length || !zone) return `<div class="warehouse-layout-shell">${hero}${warehouseLayoutEmptyHtml()}</div>`;

  const elements = zone.elements.map(element =>
    element.type === 'rack'
      ? warehouseLayoutRackHtml(element,zone,runtime,statusFilter,search)
      : warehouseLayoutObjectHtml(element,zone)
  ).join('');
  const missingOutside = zoneRuntime.unmatchedImported;
  const statusCounts = zoneRuntime.statusCounts;
  const planMetrics = planLocationMetrics(runtime,zone);
  const planPercentText = planMetrics.countPercent.toLocaleString(uiLocale(),{minimumFractionDigits:1,maximumFractionDigits:1});
  return `<div class="warehouse-layout-shell">
    ${hero}

    <section class="warehouse-layout-metric-section master">
      <div class="warehouse-layout-metric-heading"><span>ข้อมูลผังแม่</span><small>จำนวนช่องตามโครงสร้าง Layout</small></div>
      <div class="warehouse-layout-kpis">
        ${warehouseLayoutKpiHtml('Location ใน Layout',zoneRuntime.totalLayout.toLocaleString(uiLocale()),'','all',statusFilter)}
        ${warehouseLayoutKpiHtml('Plan Location · '+zone.name,planMetrics.plan ? planMetrics.plan.toLocaleString(uiLocale()) : 'ยังไม่ตั้ง','plan','none',statusFilter)}
        ${warehouseLayoutKpiHtml('Import ตรง Layout',zoneRuntime.matched.toLocaleString(uiLocale()),'matched','none',statusFilter)}
        ${warehouseLayoutKpiHtml('ความครบถ้วน',completenessText,'completeness','none',statusFilter,'%')}
      </div>
    </section>
    <section class="warehouse-layout-metric-section live">
      <div class="warehouse-layout-metric-heading"><span>สถานะงานปัจจุบัน</span><small>${escapeWmsText(runtime.sessionName || 'Session ที่เลือก')} · อัปเดตจากฐานข้อมูล</small></div>
      <div class="warehouse-layout-kpis">
        ${warehouseLayoutKpiHtml('ยังไม่ Import',statusCounts.not_imported.toLocaleString(uiLocale()),'missing','not_imported',statusFilter)}
        ${warehouseLayoutKpiHtml('Import แล้ว · รอจ่าย',statusCounts.imported.toLocaleString(uiLocale()),'imported','imported',statusFilter)}
        ${warehouseLayoutKpiHtml('จ่ายงาน / กำลังนับ',statusCounts.counting.toLocaleString(uiLocale()),'counting','counting',statusFilter)}
        ${warehouseLayoutKpiHtml('ตรวจการจับคู่ผลนับ',statusCounts.history_review.toLocaleString(uiLocale()),'counting','history_review',statusFilter)}
        ${warehouseLayoutKpiHtml('รอตรวจ Variance',statusCounts.variance.toLocaleString(uiLocale()),'variance','variance',statusFilter)}
        ${warehouseLayoutKpiHtml('รอปรับ / ปิด WMS',statusCounts.wms_pending.toLocaleString(uiLocale()),'wms-pending','wms_pending',statusFilter)}
        ${warehouseLayoutKpiHtml('เสร็จแล้ว',statusCounts.completed.toLocaleString(uiLocale()),'completed','completed',statusFilter)}
      </div>
    </section>
    <div class="warehouse-layout-workspace">
      <section class="warehouse-layout-map-card">
        <div class="warehouse-layout-map-head">
          <div><strong>Zone ${escapeWmsText(zone.name)}</strong><br><span>มุมมองตารางตามแบบ Excel · กดช่องเพื่อดูรายละเอียด Location</span></div>
          <div class="warehouse-layout-map-controls">
            <label class="warehouse-layout-control"><span>ขนาดแผนผัง</span><select onchange="setWarehouseLayoutZoom(this.value)">
              ${zoomOptions.map(value => `<option value="${value}" ${value===zoom?'selected':''}>${Math.round(value*100)}%</option>`).join('')}
            </select></label>
            <label class="warehouse-layout-control"><span>สถานะ</span><select onchange="setWarehouseLayoutStatusFilter(this.value)">
              <option value="all" ${statusFilter==='all'?'selected':''}>ทุกสถานะ</option>
              <option value="not_imported" ${statusFilter==='not_imported'?'selected':''}>ยังไม่ Import</option>
              <option value="imported" ${statusFilter==='imported'?'selected':''}>Import แล้ว</option>
              <option value="counting" ${statusFilter==='counting'?'selected':''}>จ่ายงาน / กำลังนับ</option>
              <option value="history_review" ${statusFilter==='history_review'?'selected':''}>ตรวจการจับคู่ผลนับ</option>
              <option value="variance" ${statusFilter==='variance'?'selected':''}>รอตรวจ Variance</option>
              <option value="wms_pending" ${statusFilter==='wms_pending'?'selected':''}>รอปรับ / ปิด WMS</option>
              <option value="completed" ${statusFilter==='completed'?'selected':''}>เสร็จแล้ว</option>
            </select></label>
          </div>
        </div>
        ${warehouseLayoutMatrixZoneHtml(zone,runtime,statusFilter,search,zoom)}
        ${warehouseLayoutLegendHtml()}
      </section>
      <aside class="warehouse-layout-side">
        <div class="warehouse-layout-plan">
          <div class="warehouse-layout-plan-head"><span>นับแล้วตาม Plan Location</span><strong>${planMetrics.plan ? `${planPercentText}%` : '—'}</strong></div>
          <div class="warehouse-layout-plan-track"><i style="width:${planMetrics.countPercent.toFixed(2)}%"></i></div>
          <div class="warehouse-layout-plan-foot"><span>${planMetrics.counted.toLocaleString(uiLocale())} นับแล้ว</span><span>${planMetrics.plan ? `${planMetrics.plan.toLocaleString(uiLocale())} ตามแผน` : 'ตั้งค่า Plan Location ก่อน'}</span></div>
        </div>
        <div class="warehouse-layout-progress">
          <h3>ความครบถ้วนการ Import</h3>
          <div class="warehouse-layout-donut" style="--value:${Math.max(0,Math.min(100,zoneRuntime.completeness)).toFixed(2)}">
            <strong>${completenessText}<small>%</small></strong>
          </div>
          <div style="font-size:10px;color:var(--text-muted);font-weight:700">${zoneRuntime.matched.toLocaleString(uiLocale())} / ${zoneRuntime.totalLayout.toLocaleString(uiLocale())} Location</div>
        </div>
        <div class="warehouse-layout-side-summary">
          <div class="warehouse-layout-side-row"><span>Import แล้ว ยังไม่จ่าย</span><strong>${statusCounts.imported.toLocaleString(uiLocale())}</strong></div>
          <div class="warehouse-layout-side-row"><span>Layout แต่ยังไม่ Import</span><strong>${zoneRuntime.missingImport.length.toLocaleString(uiLocale())}</strong></div>
          <div class="warehouse-layout-side-row"><span>Import ทั้งหมดใน Zone</span><strong>${zoneRuntime.totalImported.toLocaleString(uiLocale())}</strong></div>
        </div>
        <div class="warehouse-layout-alert">
          <div class="warehouse-layout-alert-head"><span>ไม่พบใน Layout</span><strong>${missingOutside.length.toLocaleString(uiLocale())}</strong></div>
          <div class="warehouse-layout-alert-list">
            ${missingOutside.slice(0,5).map(item => `<div class="warehouse-layout-alert-item">${escapeWmsText(item.code)}</div>`).join('')
              || `<div style="padding:13px 0;text-align:center;color:var(--theme-success-color);font-size:10px;font-weight:800">✓ ไม่พบปัญหา</div>`}
          </div>
          ${missingOutside.length ? `<button class="btn btn-ghost btn-sm" style="width:calc(100% - 20px);margin:5px 10px 11px" onclick="showWarehouseLayoutMatchReport(false,'${escapeWmsText(currentZoneId)}')">ดูทั้งหมด</button>` : ''}
        </div>
      </aside>
    </div>
  </div>`;
}

warehouseLayoutRackSummary:
function warehouseLayoutRackSummary(rack,runtime) {
  const skipped = new Set(rack.skipBays || []);
  const activeBays = Array.from({length:rack.bayCount},(_,index) => rack.bayStart+index).filter(bay => !skipped.has(bay));
  const counts = (rack.excludedCells || []).reduce((result,cell) => {
    const type = warehouseLayoutCellType(cell.cellType,cell.note);
    result[type] = (result[type] || 0)+1;
    return result;
  },{pillar:0,aisle:0,disabled:0});
  const rackLocations = runtime.generatedLocations.filter(location => location.rackId === rack.id);
  const live = {not_imported:0,imported:0,counting:0,history_review:0,variance:0,wms_pending:0,completed:0};
  rackLocations.forEach(location => {
    const status = runtime.detailsByCode.get(location.code)?.status || 'not_imported';
    live[status] = (live[status] || 0)+1;
  });
  return {
    total:activeBays.length*rack.levels.length,
    usable:rackLocations.length,
    disabled:counts.disabled || 0,
    pillar:counts.pillar || 0,
    aisle:counts.aisle || 0,
    diff:live.variance,
    live,
  };
}

warehouseLayoutMatrixRackHtml:
function warehouseLayoutMatrixRackHtml(rack,zone,runtime,statusFilter,search) {
  const rackLocations = runtime.generatedLocations.filter(location => location.zoneId === zone.id && location.rackId === rack.id);
  const display = warehouseLayoutRackDisplayMeta(rack,rackLocations);
  const byKey = new Map(rackLocations.map(location => [`${location.level}|${location.bay}`,location]));
  const skipped = new Set(rack.skipBays || []);
  const excluded = new Map((rack.excludedCells || []).map(cell => [warehouseExcludedCellKey(cell.level,cell.bay),cell]));
  const bays = Array.from({length:rack.bayCount},(_,index) => rack.bayStart+index);
  if (rack.direction === 'rtl') bays.reverse();
  const rows = rack.levels.map(level => `<tr>
    <th class="warehouse-matrix-level">${escapeWmsText(warehouseLayoutLevelLabel(level))}</th>
    ${bays.map(bay => {
      if (skipped.has(bay)) return '<td><span class="warehouse-matrix-skip" title="ช่องเว้นว่าง"></span></td>';
      const blocked = excluded.get(warehouseExcludedCellKey(level,bay));
      if (blocked) {
        const cellType = warehouseLayoutCellType(blocked.cellType,blocked.note);
        const red = /สีแดง/i.test(blocked.note || '') ? ' is-red' : '';
        return `<td><span class="warehouse-matrix-blocked is-${cellType}${red}" title="${escapeWmsText(warehouseLayoutCellTypeInfo(cellType).label)} · ${escapeWmsText(blocked.note || 'กำหนดเอง')}"></span></td>`;
      }
      const generated = byKey.get(`${level}|${bay}`);
      if (!generated) return '<td></td>';
      const detail = runtime.detailsByCode.get(generated.code);
      const status = detail?.status || 'not_imported';
      const statusInfo = warehouseLayoutStatusInfo(status);
      const dimmed = (statusFilter !== 'all' && status !== statusFilter) || (search && !generated.code.includes(search)) ? ' is-dimmed' : '';
      const searchHit = search && generated.code.includes(search) ? ' is-search-hit' : '';
      return `<td><button class="warehouse-matrix-cell status-${statusInfo.className}${dimmed}${searchHit}" type="button"
        data-warehouse-location-code="${escapeWmsText(generated.code)}" onclick="showWarehouseLocationDetail(this.dataset.warehouseLocationCode)"
        title="${escapeWmsText(generated.code)} · ${escapeWmsText(statusInfo.label)}" aria-label="${escapeWmsText(generated.code)} ${escapeWmsText(statusInfo.label)}"></button></td>`;
    }).join('')}
  </tr>`).join('');
  const summary = warehouseLayoutRackSummary(rack,runtime);
  return `<section class="warehouse-matrix-rack">
    <div class="warehouse-matrix-rack-name"><strong>${escapeWmsText(display.rack)}</strong><small>${display.noLevel ? 'ไม่มี LEVEL' : `ROW ${escapeWmsText(display.row)}`}</small><div class="warehouse-matrix-rack-stats">
      <span class="warehouse-matrix-stat-label">ผังแม่</span>
      <span>ช่อง ${summary.total.toLocaleString(uiLocale())}</span><span>เปิดใช้ ${summary.usable.toLocaleString(uiLocale())}</span>
      <span>ปิดใช้ ${summary.disabled.toLocaleString(uiLocale())}</span><span>เสา ${summary.pillar.toLocaleString(uiLocale())}</span>
      <span class="warehouse-matrix-stat-label">สถานะงานปัจจุบัน</span>
      <span class="live-not-imported">ยังไม่ Import ${summary.live.not_imported.toLocaleString(uiLocale())}</span><span class="live-imported">รอจ่าย ${summary.live.imported.toLocaleString(uiLocale())}</span>
      <span class="live-counting">กำลังนับ ${summary.live.counting.toLocaleString(uiLocale())}</span><span style="color:#7e22ce">ตรวจผลนับ ${summary.live.history_review.toLocaleString(uiLocale())}</span><span class="live-variance">DIFF ${summary.live.variance.toLocaleString(uiLocale())}</span>
      <span class="live-wms-pending">รอ WMS ${summary.live.wms_pending.toLocaleString(uiLocale())}</span><span class="live-completed">เสร็จแล้ว ${summary.live.completed.toLocaleString(uiLocale())}</span>
    </div></div>
    <table class="warehouse-matrix-table"><thead><tr><th class="warehouse-matrix-level">LV</th>${bays.map(bay => `<th>${escapeWmsText(String(bay).padStart(rack.bayPad,'0'))}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table>
  </section>`;
}

loadSvDashCoreV262:
async function loadSvDashCoreV262() {
  if (!['admin','supervisor'].includes(prof?.role)) {
    goPrimary('c-tasks');
    return;
  }
  const loadScope = _activePageRequestController;
  const isStaleLoad = () =>
    loadScope !== _activePageRequestController ||
    loadScope?.signal?.aborted ||
    S?.page !== 'sv-dash';
  const requestedTab = S._dashTab || _dashTab || 'summary';
  const tab = requestedTab === 'variance' ? 'wms' : requestedTab;
  S._dashTab = tab;
  _dashTab = tab;

  // A previous Layout runtime must not be repainted while the fresh database
  // request is running. The loading page remains visible until every query and
  // every result page for this Session has completed.
  if (tab === 'layout') {
    window._warehouseLayoutSessionData = null;
    window._warehouseLayoutRuntime = null;
  }

  let sessionsQuery = sb.from('count_sessions')
    .select('id,name,status,created_at')
    .order('created_at',{ascending:false});
  if (tab !== 'executive') sessionsQuery = sessionsQuery.eq('status','active');
  const { data: sessions, error:sessionsError } = await sessionsQuery;
  if (isStaleLoad()) return;
  if (sessionsError) throw sessionsError;

  if (!sessions?.length) {
    cnt().innerHTML = `<div class="card" style="text-align:center;padding:60px 40px">
      <div style="font-size:60px">🌴</div>
      <div style="margin-top:20px;color:var(--text-main);font-weight:700; font-size:16px;">${tab === 'executive' ? 'ยังไม่มี Session สำหรับวิเคราะห์' : 'ยังไม่มี Session ที่เปิดอยู่'}</div>
      ${ prof?.role === 'admin' ? `<button class="btn btn-blue" style="margin-top:24px" onclick="go('ad-manage')">📂 ไปสร้าง Session</button>` : ''}
    </div>`; return;
  }

  const rememberedSessionId = readRememberedDashboardSession();
  const curSid = resolveDashboardSessionId(sessions,S._dashSid,rememberedSessionId);
  S._dashSid = curSid;
  if (curSid) rememberDashboardSession(curSid);
  else if (rememberedSessionId) rememberDashboardSession('');
  const currentSession = sessions.find(session => String(session.id) === curSid) || {};
  const curName = currentSession.name || '';
  const sessOpts = `<option value="" ${curSid ? '' : 'selected'} disabled>— เลือกงาน —</option>`
    + sessions.map(session => {
      const statusSuffix = tab === 'executive'
        ? ` · ${session.status === 'active' ? uiCopy('เปิดอยู่','Active') : uiCopy('ปิดแล้ว','Closed')}`
        : '';
      return `<option value="${session.id}" ${String(session.id)===curSid?'selected':''}>${escapeWmsText(sessionOptionLabel(session) + statusSuffix)}</option>`;
    }).join('');

  if (!curSid) {
    cnt().innerHTML = `${dashboardSessionControlHtml(tab,sessOpts)}
      <div class="${tab === 'summary' ? 'summary-dashboard-content' : 'card'}" id="dash-content">
        <div class="dashboard-session-empty-state">
          <strong>เลือก Session เพื่อแสดงข้อมูล</strong>
          <span>ระบบจะจำ Session ที่เลือกไว้จนกว่าคุณจะเปลี่ยนเอง</span>
        </div>
      </div>`;
    updateDashboardNavigationUi(tab);
    scheduleTabletViewportLayout(false);
    disconnectTabletAccuracyLayoutGuard();
    return;
  }
  // V1.113: WMS must always use the complete live database read below. The old
  // Fast RPC and Local Storage snapshot could disagree with variance_approvals
  // and alternately hide/show the same Item when users revisited the menu.
  if (tab === 'wms') {
    invalidateWmsFastCacheV179(curSid);
    invalidateDashboardCache('wms');
    window._wmsRows = [];
    window._wmsAsgnInfoMap = {};
  }
  // Load menu-specific settings only.  V1.77 fetched both Layout documents in
  // front of almost every Dashboard tab even when they were never rendered.
  const viewVersionV271 = await readManagementViewVersionV271(curSid,tab);
  if (isStaleLoad()) return;
  if (paintVerifiedManagementCacheV263(viewVersionV271,tab,curSid,sessOpts)) return;
  const managementBundle = await loadManagementBundleV263(curSid,tab);
  if (isStaleLoad()) return;
  if (managementBundle) applyManagementSettingsV263(managementBundle);
  const dashboardSettingsPromise = managementBundle ? Promise.resolve()
    : tab === 'layout' ? Promise.all([loadWarehouseLayoutConfig(true,true),loadPlanLocationConfig(true,true)])
    : tab === 'summary' ? loadPlanLocationConfig(true,true) : Promise.resolve();


  await dashboardSettingsPromise;
  if (isStaleLoad()) return;
  if (paintVerifiedManagementCacheV263(managementBundle,tab,curSid,sessOpts)) return;
  const [
    { data: asgns, error:assignmentsError },
    { data: wmsRemarkRows, error:wmsRemarksError },
    { data: pendingFoundRows, error:pendingFoundError },
  ] = await Promise.all([
    // Count History already reads every Assignment with pagination. The review
    // pages must do the same: a direct Supabase select is capped (normally at
    // 1,000 rows), and round3_done sorts near the end, so older DIFF work could
    // disappear from both the Variance and WMS queues even while History shows it.
    managementRowsV263(managementBundle,'assignments',() => fetchPagedSupabaseRows(
      'assignments',
      'id,status,assigned_to,location_id,assigned_at,created_at,counter_r2_id,counter_r3_id,wms_closed_at,wms_closed_by,locations(code,zone,row_no,level),profiles!assigned_to(name)',
      query => query
        .eq('session_id', curSid)
        .order('status')
        .order('created_at')
        .order('id'),
    )),
    managementRowsV263(managementBundle,'remarks',() => tab === 'wms'
      ? sb.from('remark_options').select('id,label').eq('context','wms').eq('active',true).order('label')
      : Promise.resolve({ data:[],error:null })),
    managementRowsV263(managementBundle,'found',() => ['summary','executive','variance','wms'].includes(tab)
      ? fetchPagedSupabaseRows('found_items',
          'id,session_id,status,source_type,location_code,license_plate,lot,inventory_status,item_code,description,uom,qty,actual_counter_name,discovered_at,profiles!found_items_discovered_by_fkey(name)',
          query => query.eq('session_id',curSid).eq('status','pending_review')
            .order('discovered_at',{ ascending:true }).order('id'))
      : Promise.resolve({ data:[],error:null })),
    dashboardSettingsPromise,
  ]);
  if (isStaleLoad()) return;
  if (assignmentsError) throw assignmentsError;
  if (pendingFoundError) throw pendingFoundError;
  if (wmsRemarksError) console.warn('โหลดตัวเลือกหมายเหตุ WMS ไม่สำเร็จ:', wmsRemarksError);
  window._wmsNoteOptions = wmsRemarkRows || [];

  let total    = asgns.length;
  let done     = asgns.filter(assignmentPhysicalCountFinished).length;
  let varCount = asgns.filter(assignmentPendingVarianceReview).length;
  let pending  = Math.max(0,total - done);
  let pct      = total ? Math.round(done / total * 100) : 0;

  const asgnInfoMap = {};
  asgns.forEach(a => { asgnInfoMap[a.id] = a; });

  const allAsgnIds = asgns.map(a => a.id);
  const dashboardReadBundlePromise = managementBundle
    ? Promise.resolve(managementDashboardBundleV263(managementBundle,tab === 'wms'))
    : loadDashboardReadBundleV252(curSid,allAsgnIds,tab === 'wms');
  const [
    countResult,
    snapshotResult,
    detailResult,
    annualJobsResult,
    annualJobItemsResult,
    rules,
    paperResult,
    varianceApprovalResult,
    baselineAuditResult,
    dashboardReadBundle,
  ] = await Promise.all([
    dashboardBundleRowsV252(dashboardReadBundlePromise,'counts',() => fetchSupabaseRowsByValues(
      'count_records',
      'id,assignment_id,item_id,round,count_qty,counted_by,counted_at,actual_counter_name,type_issue,remark,photo_url',
      'assignment_id',
      allAsgnIds,
      query => query.order('id'),
    )),
    managementRowsV263(managementBundle,'snapshots',() => fetchPagedSupabaseRows(
