  wmsRows.forEach(v => {
    const key = `${v.assignment_id}|${v.item_id}`;
    if (!v.wms_fixed && wmsStatusAuditMap[key] === true) {
      v.wms_fixed = true;
      v._wmsFixedRecoveredFromAudit = true;
    }
    v.items = itemMap[v.item_id] || { code: '?', description: '' };
    v.profiles = approverMap[v.approved_by] || { name: '?' };
    v.wms_notes = historicalWmsNotesFor(v.assignment_id,v.item_id,v);
  });

  // An approved item must never be recreated as "รอคอนเฟิร์ม".
  // Use the assignment + item key because one assignment can contain several items.
  const approvedItemKeys = new Set(
    trackerApprovalRows.map(v => `${v.assignment_id || ''}|${v.item_id || ''}`)
  );
  const approvalAssignmentIds = new Set(
    trackerApprovalRows
      .filter(v => Number(v.variance) !== 0)
      .map(v => v.assignment_id)
      .filter(Boolean)
  );
  const pendingWmsRows = [];
  for (const a of diffAssignments) {
    const itemCounts = sessionCountByAsgn[a.id] || {};
    const locId = a.location_id;
    const pendingStartIndex = pendingWmsRows.length;
    const persistedFallbackCandidates = [];
    for (const [itemId, rounds] of Object.entries(itemCounts)) {
      if (approvedItemKeys.has(`${a.id}|${itemId}`)) continue;
      const oh = ohMap[locId + '|' + itemId];
      const latestRound = rounds[3] !== undefined ? 3 : rounds[2] !== undefined ? 2 : 1;
      const countQty = rounds[latestRound];
      if (oh === undefined) {
        if (a._storedNeedsSupervisorReview) {
          persistedFallbackCandidates.push({ itemId,rounds,countQty,reason:'snapshot_missing' });
        }
        continue;
      }
      const st = computeItemStatus(oh, rounds[1], rounds[2], rounds[3], rules);
      if (!a._storedNeedsSupervisorReview && st !== 'Diff') continue;
      const variance = countQty - oh;
      if (Number(variance) === 0) {
        if (a._storedNeedsSupervisorReview) {
          persistedFallbackCandidates.push({ itemId,rounds,countQty,oh,reason:'snapshot_changed' });
        }
        continue;
      }
      pendingWmsRows.push({
        _isPending: true,
        assignment_id: a.id,
        item_id: itemId,
        final_qty: countQty,
        variance: variance,
        resolution:'pending_diff',
        approved_by: null,
        wms_fixed: false,
        wms_fixed_at: null,
        wms_fixed_by: null,
        created_at: null,
        items: { code: '?', description: '' },
        profiles: { name: '(ยังไม่คอนเฟิร์ม)' },
        wms_notes: historicalWmsNotesFor(a.id,itemId),
      });
    }

    // round3_done is a persisted workflow fact. If every item was lost only
    // because today's Snapshot is missing/changed, keep one assignment-level
    // review row visible instead of silently reporting zero DIFF.
    if (
      a._storedNeedsSupervisorReview
      && pendingWmsRows.length === pendingStartIndex
      && !approvalAssignmentIds.has(a.id)
    ) {
      let fallback = persistedFallbackCandidates[0];
      if (!fallback) {
        const firstItemId = Object.keys(itemCounts)[0]
          || (snapshotsByLocation[a.location_id] || [])[0]?.item_id
          || '';
        if (firstItemId) {
          const rounds = itemCounts[firstItemId] || {};
          const latestRound = rounds[3] !== undefined ? 3 : rounds[2] !== undefined ? 2 : 1;
          fallback = {
            itemId:firstItemId,
            rounds,
            countQty:rounds[latestRound] ?? null,
            oh:ohMap[locId + '|' + firstItemId],
            reason:'persisted_status',
          };
        }
      }
      if (fallback?.itemId) {
        pendingWmsRows.push({
          _isPending:true,
          _persistedReviewFallback:true,
          _persistedReviewReason:fallback.reason,
          assignment_id:a.id,
          item_id:fallback.itemId,
          final_qty:fallback.countQty,
          variance:null,
          resolution:'pending_persisted_review',
          approved_by:null,
          wms_fixed:false,
          wms_fixed_at:null,
          wms_fixed_by:null,
          created_at:null,
          items:{ code:'?', description:'' },
          profiles:{ name:'(รอตรวจสอบข้อมูลเดิม)' },
          wms_notes:historicalWmsNotesFor(a.id,fallback.itemId),
        });
      }
    }
  }

  const pendingItemIds = [...new Set(pendingWmsRows.map(v => v.item_id).filter(Boolean))];
  if (pendingItemIds.length) {
    const { data: pendingItems, error:pendingItemsError } = await managementRowsV263(managementBundle,'items',() => fetchSupabaseRowsByValues(
      'items',
      'id,code,description',
      'id',
      pendingItemIds,
      query => query.order('id'),
    ));
    if (isStaleLoad()) return;
    requireManagementRowsV271({data:pendingItems,error:pendingItemsError});
    const pItemMap = Object.fromEntries((pendingItems||[]).map(i => [i.id, i]));
    pendingWmsRows.forEach(v => { v.items = pItemMap[v.item_id] || { code: '?', description: '' }; });
  }
  if (isStaleLoad()) return;

  // The date control is global for this Dashboard. A WMS result belongs to the
  // date of its latest/final count for that Assignment + Item—not every date on
  // which the same Assignment happened to receive an earlier counting round.
  const sessionWmsRows = [...wmsRows, ...pendingWmsRows];
  const latestWmsCountAt = new Map();
  rawCounts.forEach(record => {
    if (!record.assignment_id || !record.item_id || !record.counted_at) return;
    const time = new Date(record.counted_at).getTime();
    if (!Number.isFinite(time)) return;
    const key = `${record.assignment_id}|${record.item_id}`;
    const previous = latestWmsCountAt.get(key);
    if (!previous || time > previous.time) {
      latestWmsCountAt.set(key,{ time, value:record.counted_at });
    }
  });
  sessionWmsRows.forEach(row => {
    const key = `${row.assignment_id || ''}|${row.item_id || ''}`;
    row._dashboardCountedAt = latestWmsCountAt.get(key)?.value
      || row.approved_at
      || row.created_at
      || null;
  });
  // WMS is an operational queue: when that tab is open it must show every Item
  // in the selected Session regardless of a date range left from another tab.
  const wmsWorkspaceRows = tab === 'wms'
    ? sessionWmsRows
    : activeDateFilter
      ? filterRowsByDashboardDate(sessionWmsRows,'_dashboardCountedAt')
      : sessionWmsRows;
  const allWmsRows = wmsWorkspaceRows;
  wmsWorkspaceRows.forEach(v => {
    const assignment = asgnInfoMap[v.assignment_id];
    const rounds = sessionCountByAsgn[v.assignment_id]?.[v.item_id] || {};
    const ohKey = `${assignment?.location_id || ''}|${v.item_id || ''}`;
    v._oh = ohMap[ohKey];
    v._count1 = rounds[1];
    v._count2 = rounds[2];
    v._count3 = rounds[3];
  });
  window._wmsRows = wmsWorkspaceRows;
  window._wmsAsgnInfoMap = asgnInfoMap;
  window._actualCountersByAssignment = actualCountersByAssignment;
  window._actualCountersByWork = actualCountersByWork;
  window._wmsHistoryLoading = false;


  if (tab === 'wms') {
  restoreWmsPersistedFiltersV22(curSid);
  restoreWmsActiveWorkflowV25(curSid);
  const allowedWmsStatuses = new Set(['all','unfixed','fixed','pending']);
  const requestedWmsFilter = S._wmsFilter || 'all';
  const wmsFilter = allowedWmsStatuses.has(requestedWmsFilter) ? requestedWmsFilter : 'all';
  // An empty result is valid. Never replace the User's selected status just
  // because the last matching Item was confirmed, edited or closed.
  S._wmsFilter = wmsFilter;
  const wmsZone = S._wmsZone || '';
  const wmsRow = S._wmsRow || '';
  const wmsLevel = S._wmsLevel || '';
  const wmsUser = S._wmsUser || '';
  const wmsCounter = S._wmsCounter || '';
  const wmsLocSearch = S._wmsLocSearch || '';

  const wmsZones = new Set(), wmsRowsNo = new Set(), wmsLevels = new Set();
  const wmsCounters = new Set();
  const wmsUsersMap = {};
  wmsWorkspaceRows.forEach(v => {
    const loc = asgnInfoMap[v.assignment_id]?.locations || {};
    const locationMeta = warehouseLocationFilterMeta(loc);
    if (locationMeta.zone) wmsZones.add(locationMeta.zone);
    if (locationMeta.row) wmsRowsNo.add(locationMeta.row);
    if (locationMeta.level) wmsLevels.add(locationMeta.level);
    if (v.approved_by) wmsUsersMap[v.approved_by] = v.profiles?.name || '?';
    else if (v._isPending) wmsUsersMap['_pending'] = '(รอคอนเฟิร์ม)';
    (actualCountersByAssignment[v.assignment_id] || []).forEach(name => {
      const normalizedName = String(name || '').trim();
      if (normalizedName) wmsCounters.add(normalizedName);
    });
  });

  const wmsTotalCount = wmsWorkspaceRows.length;
  const wmsPendingRows = wmsWorkspaceRows.filter(v => v._isPending);
  const wmsConfirmedRows = wmsWorkspaceRows.filter(v => !v._isPending);
  const wmsFixedRows = wmsConfirmedRows.filter(v => v.wms_fixed);
  const wmsUnfixedRows = wmsConfirmedRows.filter(v => !v.wms_fixed);
  const wmsPendingCount = wmsPendingRows.length;
  const wmsFixedCount = wmsFixedRows.length;
  const wmsUnfixedCount = wmsUnfixedRows.length;
  const wmsFixedPercent = wmsTotalCount > 0
    ? Math.round((wmsFixedCount / wmsTotalCount) * 100)
    : 0;
  const wmsPendingMetrics = workflowQuantityMetrics(wmsPendingRows,asgnInfoMap);
  const wmsUnfixedMetrics = workflowQuantityMetrics(wmsUnfixedRows,asgnInfoMap);
  const wmsFixedMetrics = workflowQuantityMetrics(wmsFixedRows,asgnInfoMap);
  const wmsClosureMetrics = wmsLocationClosureMetrics(wmsWorkspaceRows,asgnInfoMap);

  const errorBanner = vaError 
    ? `<div class="alert alert-red" style="margin-bottom:14px;font-size:13px">⚠️ ไม่สามารถดึงข้อมูลคอนเฟิร์มแล้วได้</div>`
    : '';

  const wmsTabHtml = `
    ${errorBanner}
    <div class="wms-workspace">
      <section class="wms-overview-shell">
        <div class="wms-overview-head">
          <div class="wms-overview-title">
            <div class="wms-overview-icon">${wmsIconSvg('reviewed',25)}</div>
            <div class="wms-overview-copy">
              <strong>ศูนย์ยืนยันผลและปรับสต๊อกสินค้า</strong>
              <span>ยืนยันผล DIFF ตรวจสอบรายการ และปิดงาน WMS ได้ในหน้าเดียว</span>
            </div>
          </div>
          <div class="wms-overview-total">
            <strong id="wms-total-count">${wmsTotalCount}</strong>
            <span>DIFF ทั้งหมด</span>
          </div>
        </div>
        <div class="wms-progress-row">
          <span>ความคืบหน้าการตรวจสอบทั้งหมด</span>
          <strong id="wms-fixed-percent">${wmsFixedPercent}%</strong>
        </div>
        <div class="wms-progress-track"><span id="wms-fixed-progress" style="width:${wmsFixedPercent}%"></span></div>
        <div class="wms-kpi-grid">
          <button type="button" class="wms-kpi-card pending ${wmsFilter==='pending'?'active':''}" data-wms-kpi="pending"
            onclick="setWmsStatusFilter('pending')">
            <div class="wms-kpi-icon">${wmsIconSvg('search',21)}</div>
            <div class="wms-kpi-copy"><strong id="wms-pending-count">${wmsPendingCount}</strong><span>รอยืนยันผล</span></div>
            ${workflowStatusDetailsHtml(wmsPendingMetrics)}
          </button>
          <button type="button" class="wms-kpi-card unfixed ${wmsFilter==='unfixed'?'active':''}" data-wms-kpi="unfixed"
            onclick="setWmsStatusFilter('unfixed')">
            <div class="wms-kpi-icon">${wmsIconSvg('pending',21)}</div>
            <div class="wms-kpi-copy"><strong id="wms-unfixed-count">${wmsUnfixedCount}</strong><span>รอตรวจสอบ</span></div>
            ${workflowStatusDetailsHtml(wmsUnfixedMetrics)}
          </button>
          <button type="button" class="wms-kpi-card fixed has-location-close-summary ${wmsFilter==='fixed'?'active':''}" data-wms-kpi="fixed"
            onclick="setWmsStatusFilter('fixed')">
            <div class="wms-kpi-icon">${wmsIconSvg('reviewed',21)}</div>
            <div class="wms-kpi-copy"><strong id="wms-fixed-count">${wmsFixedCount}</strong><span>ตรวจสอบเสร็จสิ้น</span></div>
            ${wmsClosedLocationSummaryHtml(wmsClosureMetrics)}
            ${workflowStatusDetailsHtml(wmsFixedMetrics)}
          </button>
        </div>
      </section>

      ${pendingFoundVarianceHtml(visiblePendingFoundRows)}

      <section class="wms-filter-panel">
        <div class="wms-filter-heading">
          <strong>ตัวกรองรายการ</strong>
          <span>เลือกหลายตัวกรองร่วมกันได้</span>
        </div>
        <div class="wms-filter-grid">
          <div class="wms-filter-field"><label>ZONE</label>
            <select id="wms-zone" onchange="updateWmsFilter('Zone',this.value)">
              <option value="">ทั้งหมด</option>
              ${[...wmsZones].sort().map(z=>`<option value="${z}" ${wmsZone===z?'selected':''}>${z}</option>`).join('')}
            </select>
          </div>
          <div class="wms-filter-field"><label>ROW</label>
            <select id="wms-row" onchange="updateWmsFilter('Row',this.value)">
              <option value="">ทั้งหมด</option>
              ${[...wmsRowsNo].sort((a,b)=>String(a).localeCompare(String(b),undefined,{numeric:true})).map(row=>`<option value="${row}" ${String(wmsRow)===String(row)?'selected':''}>${row}</option>`).join('')}
            </select>
          </div>
          <div class="wms-filter-field"><label>LEVEL</label>
            <select id="wms-level" onchange="updateWmsFilter('Level',this.value)">
              <option value="">ทั้งหมด</option>
              ${[...wmsLevels].sort().map(l=>`<option value="${l}" ${wmsLevel===l?'selected':''}>${l}</option>`).join('')}
            </select>
          </div>
          <div class="wms-filter-field"><label>USER ผู้คอนเฟิร์ม</label>
            <select id="wms-user" onchange="updateWmsFilter('User',this.value)">
              <option value="">ทั้งหมด</option>
              <option value="_pending" ${wmsUser==='_pending'?'selected':''}>รอคอนเฟิร์ม</option>
              ${Object.entries(wmsUsersMap).filter(([k]) => k !== '_pending').sort((a,b)=>a[1].localeCompare(b[1])).map(([id,name])=>`<option value="${id}" ${wmsUser===id?'selected':''}>${name}</option>`).join('')}
            </select>
          </div>
          <div class="wms-filter-field"><label>ผู้ตรวจนับ</label>
            <select id="wms-counter" onchange="updateWmsFilter('Counter',this.value)">
              <option value="">ทั้งหมด</option>
              ${[...wmsCounters].sort((a,b)=>a.localeCompare(b,'th')).map(name=>`<option value="${escapeWmsText(name)}" ${wmsCounter===name?'selected':''}>${escapeWmsText(name)}</option>`).join('')}
            </select>
          </div>
          <div class="wms-filter-field"><label>สถานะ</label>
            <select id="wms-status" onchange="updateWmsFilter('Filter',this.value)">
              <option value="all" ${wmsFilter==='all'?'selected':''}>ทั้งหมด</option>
              <option value="unfixed" ${wmsFilter==='unfixed'?'selected':''}>ยังไม่ได้ตรวจสอบ</option>
              <option value="fixed" ${wmsFilter==='fixed'?'selected':''}>ตรวจสอบแล้ว</option>
              <option value="pending" ${wmsFilter==='pending'?'selected':''}>รอคอนเฟิร์ม</option>
            </select>
          </div>
          <div class="wms-filter-field search"><label>ค้นหา LOCATION / ITEM</label>
            <input id="wms-loc-search" value="${escapeWmsText(wmsLocSearch)}" placeholder="เช่น B-29-001-A หรือรหัส Item"
              oninput="updateWmsFilter('LocSearch',this.value)">
          </div>
        </div>
        <div class="wms-feedback" id="wms-feedback" role="status" aria-live="polite" hidden></div>
      </section>

      <section class="wms-list-shell">
        <div class="wms-list-heading">
          <strong>รายการปรับยอด</strong>
          <span class="wms-list-count" id="wms-visible-count">0 รายการ</span>
        </div>
        <div id="wms-list" data-location-sort-group></div>
      </section>
    </div>`;

    paintManagementTabV263(tab,curSid,sessOpts,wmsTabHtml);
    return;
  }

  // One accuracy record represents one physical Location + Item pair.
  // Counting rounds and reassignment must not create additional accuracy items.
  const accuracyLocationItemKey = (assignmentId, itemId) => {
    const assignment = asgnInfoMap[assignmentId];
    const locationKey = assignment?.location_id || assignment?.locations?.code || assignmentId;
    return locationKey && itemId ? `${locationKey}|${itemId}` : '';
  };

  let diffPlus = 0, diffMinus = 0;
  const gainItemKeys = new Set();
  const lostItemKeys = new Set();
  allWmsRows.forEach(v => {
    const d = +v.variance;
    const itemKey = accuracyLocationItemKey(v.assignment_id, v.item_id);
    if (d > 0) {
      diffPlus += d;
      if (itemKey && !emptyLocationItemIds.has(v.item_id)) gainItemKeys.add(itemKey);
    } else if (d < 0) {
      diffMinus += Math.abs(d);
      if (itemKey && !emptyLocationItemIds.has(v.item_id)) lostItemKeys.add(itemKey);
    }
  });
  const gainItemCount = gainItemKeys.size;
  const lostItemCount = lostItemKeys.size;
  const okItemKeys = new Set();
  let okQty = 0;
  Object.entries(countByAsgn).forEach(([assignmentId, itemRows]) => {
    const assignment = asgnInfoMap[assignmentId];
    if (!assignment) return;
    Object.entries(itemRows || {}).forEach(([itemId, rounds]) => {
      if (emptyLocationItemIds.has(itemId)) return;
      const oh = ohMap[`${assignment.location_id}|${itemId}`];
      if (oh === undefined) return;
      if (computeItemStatus(oh, rounds[1], rounds[2], rounds[3], rules) !== 'OK') return;
      const key = accuracyLocationItemKey(assignmentId, itemId);
      if (!key) return;
      if (okItemKeys.has(key)) return;
      okItemKeys.add(key);
      const finalCount = rounds[3] ?? rounds[2] ?? rounds[1] ?? oh;
      okQty += Number(finalCount) || 0;
    });
  });
  const okItemCount = okItemKeys.size;

  let totalOHQty = 0;
  Object.values(ohMap).forEach(qty => totalOHQty += qty);

  let uniqueSKUs = new Set();
  let uniqueLocations = new Set();
  (allSnapshots||[]).forEach(s => {
    if (!emptyLocationItemIds.has(s.item_id)) uniqueSKUs.add(s.item_id);
    uniqueLocations.add(s.location_id);
  });
  let totalSKUs = uniqueSKUs.size;
  let totalLocations = uniqueLocations.size;

  let absVariance = diffPlus + diffMinus;

  // v128 — use one Stock Accuracy definition everywhere:
  // correct Location + Item pairs / all counted Location + Item pairs.
  // This intentionally does not use stock quantity as the denominator, so the
  // overall card and each Zone remain directly comparable.
  const countedAccuracyItemKeys = new Set();
  (allCounts || []).forEach(c => {
    if (!c.assignment_id || !c.item_id || emptyLocationItemIds.has(c.item_id)) return;
    const itemKey = accuracyLocationItemKey(c.assignment_id, c.item_id);
    if (itemKey) countedAccuracyItemKeys.add(itemKey);
  });
  const diffAccuracyItemKeys = new Set();
  (allWmsRows || []).forEach(v => {
    if (!v.assignment_id || !v.item_id || emptyLocationItemIds.has(v.item_id)) return;
    if (Number(v.variance) === 0) return;
    const itemKey = accuracyLocationItemKey(v.assignment_id, v.item_id);
    if (countedAccuracyItemKeys.has(itemKey)) diffAccuracyItemKeys.add(itemKey);
  });
  const totalAccuracyItems = countedAccuracyItemKeys.size;
  const correctAccuracyItems = Math.max(0, totalAccuracyItems - diffAccuracyItemKeys.size);
  let stockAccuracy = totalAccuracyItems > 0
    ? ((correctAccuracyItems / totalAccuracyItems) * 100).toFixed(2)
    : '0.00';
  let stockAccuracyNum = Number(stockAccuracy) || 0;
  const diffPct = totalOHQty > 0 ? ((absVariance / totalOHQty) * 100).toFixed(2) : '0.00';
  const diffPctNum = Number(diffPct) || 0;

  const varianceRowsOnly = allWmsRows.filter(v => Number(v.variance) !== 0);
  const diffLocationSet = new Set();
  const diffItemSet = new Set();
  varianceRowsOnly.forEach(v => {
    const locKey = asgnInfoMap[v.assignment_id]?.location_id || asgnInfoMap[v.assignment_id]?.locations?.code || v.assignment_id;
    if (locKey) diffLocationSet.add(locKey);
    if (v.item_id && !emptyLocationItemIds.has(v.item_id)) diffItemSet.add(v.item_id);
  });
  const diffLocationPct = totalLocations > 0 ? ((diffLocationSet.size / totalLocations) * 100).toFixed(2) : '0.00';
  const diffItemPct = totalSKUs > 0 ? ((diffItemSet.size / totalSKUs) * 100).toFixed(2) : '0.00';

  const countedAssignmentIds = new Set((allCounts || []).map(c => c.assignment_id).filter(Boolean));
  const countedAssignments = asgns.filter(a => countedAssignmentIds.has(a.id));
  const countedLocationSet = new Set();
  const countedCounterSet = new Set();
  countedAssignments.forEach(a => {
    if (a.location_id) countedLocationSet.add(a.location_id);
    else if (a.locations?.code) countedLocationSet.add(a.locations.code);
  });
  (allCounts || []).forEach(c => {
    splitActualCounterNames(c.actual_counter_name).forEach(name => countedCounterSet.add(name));
  });
  const countedItemSet = new Set();
  const countedOhKeys = new Set();
  (allCounts || []).forEach(c => {
    const asgn = asgnInfoMap[c.assignment_id];
    if (!asgn) return;
    if (c.item_id && !emptyLocationItemIds.has(c.item_id)) countedItemSet.add(c.item_id);
    const locKey = asgn.location_id || asgn.locations?.code;
    if (locKey && c.item_id) countedOhKeys.add(locKey + '|' + c.item_id);
  });
  totalLocations = countedLocationSet.size;
  totalSKUs = countedItemSet.size;
  totalOHQty = 0;
  countedOhKeys.forEach(key => {
    if (ohMap[key] !== undefined) totalOHQty += Number(ohMap[key]) || 0;
  });
  // stockAccuracy already follows the same item-based formula for both the
  // full Session and the selected dashboard date range because allCounts is
  // filtered before the Location + Item sets above are created.
  const totalCounters = countedCounterSet.size;

  // One dashboard work unit is exactly one physical Location + one Item.
  // Counting rounds must never increase the number of jobs. A Location with
  // no stock rows is retained as one EMPTY work unit so empty locations can
  // still be counted normally.
  const summaryWorkKey = (assignmentId,itemId,fallbackItem='__EMPTY__') => {
    const assignment = asgnInfoMap[assignmentId];
    const locationKey = assignment?.location_id || assignment?.locations?.code || assignmentId;
    if (!locationKey) return '';
    return `${locationKey}|${itemId || fallbackItem || '__EMPTY__'}`;
  };
  const plannedWorkSet = new Set();
  dashboardAssignments.forEach(assignment => {
    const locationKey = assignment.location_id || assignment.locations?.code || assignment.id;
    if (!locationKey) return;
    const locationSnapshots = operationalStockSnapshotRows(snapshotsByLocation[assignment.location_id] || []);
    if (!locationSnapshots.length) {
      plannedWorkSet.add(`${locationKey}|__EMPTY__`);
      return;
    }
    locationSnapshots.forEach(snapshot => {
      plannedWorkSet.add(`${locationKey}|${snapshot.item_id || snapshot.items?.code || '__EMPTY__'}`);
    });
  });
  const countedWorkSet = new Set();
  (allCounts || []).forEach(record => {
    const key = summaryWorkKey(record.assignment_id,record.item_id);
