  const zoneAccuracyMap = {};
  (rawCounts || []).forEach(c => {
    const asgn = asgnInfoMap[c.assignment_id];
    if (!asgn) return;
    const zone = asgn.locations?.zone || 'ไม่ระบุ Zone';
    if (!zoneAccuracyMap[zone]) zoneAccuracyMap[zone] = { countedItems: new Set(), diffItems: new Set() };
    if (c.item_id && !emptyLocationItemIds.has(c.item_id)) {
      const itemKey = accuracyLocationItemKey(c.assignment_id, c.item_id);
      if (itemKey) zoneAccuracyMap[zone].countedItems.add(itemKey);
    }
  });
  (sessionWmsRows || []).forEach(v => {
    const asgn = asgnInfoMap[v.assignment_id];
    if (!asgn) return;
    const zone = asgn.locations?.zone || 'ไม่ระบุ Zone';
    if (!zoneAccuracyMap[zone]) zoneAccuracyMap[zone] = { countedItems: new Set(), diffItems: new Set() };
    if (Number(v.variance) !== 0 && v.item_id && !emptyLocationItemIds.has(v.item_id)) {
      const itemKey = accuracyLocationItemKey(v.assignment_id, v.item_id);
      if (zoneAccuracyMap[zone].countedItems.has(itemKey)) {
        zoneAccuracyMap[zone].diffItems.add(itemKey);
      }
    }
  });

  const zoneStats = Object.entries(zoneMap).map(([zone, z]) => {
    const acc = zoneAccuracyMap[zone] || { countedItems: new Set(), diffItems: new Set() };
    const countedItems = acc.countedItems.size;
    const diffItems = acc.diffItems.size;
    const planLocations = planLocationForZone(zone);
    const progressPct = planLocations
      ? Math.min(100, Math.round((z.done.size / planLocations) * 100))
      : 0;
    const accuracyPct = countedItems
      ? (Math.max(0, ((countedItems - diffItems) / countedItems) * 100)).toFixed(2)
