        <div class="summary-zone-kpi-v126 counted"><span>ตรวจนับแล้ว</span><strong>${z.done.toLocaleString(uiLocale())}</strong><small class="summary-zone-kpi-unit-v199" data-i18n-skip>Location</small></div>
        <div class="summary-zone-kpi-v126 remaining"><span>คงเหลือ</span><strong>${Math.max(0,z.total-z.done).toLocaleString(uiLocale())}</strong><small class="summary-zone-kpi-unit-v199" data-i18n-skip>Location</small></div>
        <div class="summary-zone-kpi-v126 diff"><span>DIFF</span><strong>${z.diffItems.toLocaleString(uiLocale())}</strong><small class="summary-zone-kpi-unit-v199" data-i18n-skip>งาน</small></div>
