  // Hourly chart follows the selected dashboard date range. Count each
  // Location + Item work unit once, using its first Count record time.
  const validCountRows = (allCounts || []).filter(c => c.counted_at && !Number.isNaN(new Date(c.counted_at).getTime()));
  const localDateKey = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  let latestCountDateKey = '';
  let latestCountDate = null;
