  const hourlyRaw = Array(24).fill(0);
  Object.values(firstCountByWork).forEach(d => { hourlyRaw[d.getHours()]++; });
  const nonZeroHours = hourlyRaw.map((n,h) => n ? h : -1).filter(h => h >= 0);
  let chartStartHour = 8, chartEndHour = 19;
  if (nonZeroHours.length) {
    chartStartHour = Math.max(0, Math.min(...nonZeroHours) - 1);
    chartEndHour = Math.min(23, Math.max(...nonZeroHours) + 1);
    while (chartEndHour - chartStartHour < 7) {
      if (chartEndHour < 23) chartEndHour++;
      else if (chartStartHour > 0) chartStartHour--;
      else break;
    }
