  const stepX = chartHours.length > 1 ? plotW / (chartHours.length - 1) : plotW;
  const maxHourly = Math.max(...chartHours.map(h => hourlyRaw[h] || 0), 1);
  const points = chartHours.map((h, i) => {
    const v = hourlyRaw[h] || 0;
    const x = m.left + (i * stepX);
    const y = m.top + plotH - ((v / maxHourly) * (plotH - 8));
    return { h, v, x, y };
  });
  // Catmull-Rom → cubic Bézier: gentle curve that still passes through every real data point.
  const smoothHourlyPath = chartPoints => {
    if (!chartPoints.length) return '';
    if (chartPoints.length === 1) return `M ${chartPoints[0].x} ${chartPoints[0].y}`;
    const curveStrength = .16;
    const clampY = value => Math.max(m.top, Math.min(m.top + plotH, value));
    let path = `M ${chartPoints[0].x} ${chartPoints[0].y}`;
    for (let i = 0; i < chartPoints.length - 1; i++) {
      const p0 = chartPoints[i - 1] || chartPoints[i];
      const p1 = chartPoints[i];
      const p2 = chartPoints[i + 1];
      const p3 = chartPoints[i + 2] || p2;
      const c1x = p1.x + ((p2.x - p0.x) * curveStrength);
      const c1y = clampY(p1.y + ((p2.y - p0.y) * curveStrength));
      const c2x = p2.x - ((p3.x - p1.x) * curveStrength);
      const c2y = clampY(p2.y - ((p3.y - p1.y) * curveStrength));
      path += ` C ${c1x.toFixed(2)} ${c1y.toFixed(2)}, ${c2x.toFixed(2)} ${c2y.toFixed(2)}, ${p2.x.toFixed(2)} ${p2.y.toFixed(2)}`;
    }
    return path;
  };
  const linePath = smoothHourlyPath(points);
  const chartBaseY = m.top + plotH;
  const areaPath = points.length
    ? `${linePath} L ${points[points.length - 1].x} ${chartBaseY} L ${points[0].x} ${chartBaseY} Z`
