    </div>
    <div id="udetail_${idx}" data-location-sort-group style="display:none;background:var(--theme-card-bg);padding:14px 18px;border-radius:16px;margin:8px 0 14px;box-shadow:inset 0 0 0 1px var(--theme-border-color)">
    </div>`;
  });

  _svDashOpenVarianceIdx = null;
  // The Variance page and the WMS workspace must use the same item-level
