  const confirmedVarianceRows = varianceWorkflowRows.filter(row => !row._isPending);
  const varianceWorkflowTotal = varianceWorkflowRows.length;
  const varianceWorkflowForwarded = confirmedVarianceRows.length;
  const varianceWorkflowPercent = varianceWorkflowTotal
