    allWmsRows.filter(v => +v.variance !== 0),
    row => asgnInfoMap[row.assignment_id]?.locations?.code,
  ).slice(0, 5);
  if (recentVars.length > 0) {
    varianceReportRows = recentVars.map(v => {
      const d = +v.variance;
      const color = d > 0 ? 'var(--accent-green)' : 'var(--accent-red)';
      const sign = d > 0 ? '+' : '';
      const loc = asgnInfoMap[v.assignment_id]?.locations?.code || '?';
