  (tab === 'team' ? Object.values(byCounter) : []).sort((a,b) => a.name.localeCompare(b.name, 'th')).forEach((counter, idx) => {
    const items = sortRowsByLocation([...counter.assignmentMap.values()], assignment => assignment.locations?.code);
