      var: items.filter(assignmentPendingVarianceReview).length,
    };
    u.pending = Math.max(0,u.total - u.done);
    const p = Math.round(u.done / u.total * 100);
    // Keep the complete verified detail data off-DOM until this person opens.
    teamDetailGroupsV272[idx] = u.items.map(a => ({id:a.id,status:a.status,locations:{...a.locations}}));
    peopleRows += `<div class="tab-row" style="border-bottom:1px solid var(--theme-border-color);padding:14px 10px" onclick="toggleCounterDetail('${idx}')">
      <div style="display:flex;flex-wrap:wrap;align-items:center;gap:12px">
