          <div style="display:flex;gap:8px;margin-top:8px;flex-wrap:wrap">
            <span class="tag tag-green">${u.done} นับครบ</span>
            ${u.var ? `<span class="tag tag-amber">${u.var} DIFF รอหัวหน้า</span>` : ''}
