        </div>
        <div style="text-align:right;flex-shrink:0">
          <div style="font-size:26px;font-weight:800;color:var(--primary-blue);font-family:'Fredoka'">${p}%</div>
          <div style="font-size:12px;color:var(--text-muted);font-weight:700">นับครบ ${u.done}/${u.total}</div>
        </div>
      </div>
      <div style="text-align:center;font-size:12px;color:var(--text-muted);font-weight:700;margin-top:10px">▾ ดูรายการ</div>
    </div>
    <div id="udetail_${idx}" data-location-sort-group style="display:none;background:var(--theme-card-bg);padding:14px 18px;border-radius:16px;margin:8px 0 14px;box-shadow:inset 0 0 0 1px var(--theme-border-color)">
    </div>`;
  });

  const teamProgressTabHtml = tab === 'team' ? `
    <div>
      <div style="font-size:18px;font-weight:800;color:var(--text-main);margin-bottom:18px">👥 ความคืบหน้าตามงานที่ได้รับมอบหมาย (Team Progress)</div>
      ${peopleRows || `<div style="padding:30px 0;text-align:center;color:var(--text-muted);font-size:14px;font-weight:600">ยังไม่มีงานที่ได้รับมอบหมาย</div>`}
    </div>` : '';

return {html:teamProgressTabHtml,teamDetailGroupsV272};
